import 'package:flutter/material.dart'; import 'package:local_auth/local_auth.dart'; class LockScreen extends StatefulWidget { final Widget child; const LockScreen({super.key, required this.child}); @override State<LockScreen> createState() => _LockScreenState(); } class _LockScreenState extends State<LockScreen> { bool unlocked=false; final auth=LocalAuthentication(); @override void initState(){super.initState(); _auth();} Future<void> _auth() async { try { final did = await auth.authenticate(localizedReason: 'Unlock Ozioma'); if(did) setState(()=>unlocked=true); } catch(e){ setState(()=>unlocked=true); } } @override Widget build(BuildContext context){ if(unlocked) return widget.child; return Scaffold(body: Center(child: Column(mainAxisAlignment: MainAxisAlignment.center, children:[Icon(Icons.lock, size:64), SizedBox(height:16), Text('Ozioma is locked'), SizedBox(height:16), FilledButton(onPressed:_auth, child:Text('Unlock with Biometrics'))]))); } }
